import type { ReactNode } from 'react';

interface IconButtonProps {
  icon: ReactNode;
  label: string;
  onClick: () => void;
}

export function IconButton({ icon, label, onClick }: IconButtonProps) {
  return (
    <button
      type="button"
      aria-label={label}
      onClick={onClick}
      className="inline-flex h-9 w-9 items-center justify-center rounded-md hover:bg-gray-100 focus-visible:outline focus-visible:outline-2"
    >
      {icon}
    </button>
  );
}

import { useId } from 'react';

interface SearchInputProps {
  label: string;
  placeholder?: string;
  onChange: (value: string) => void;
}

export function SearchInput({ label, placeholder, onChange }: SearchInputProps) {
  const id = useId();
  return (
    <div className="flex flex-col gap-1">
      <label htmlFor={id} className="text-sm font-medium">
        {label}
      </label>
      <input
        id={id}
        type="search"
        placeholder={placeholder}
        onChange={(e) => onChange(e.target.value)}
        className="rounded-md border px-3 py-2"
      />
    </div>
  );
}

interface ToggleProps {
  label: string;
  checked: boolean;
  onChange: (checked: boolean) => void;
}

export function Toggle({ label, checked, onChange }: ToggleProps) {
  return (
    <button
      type="button"
      role="switch"
      aria-checked={checked}
      aria-label={label}
      onClick={() => onChange(!checked)}
      className={checked ? 'h-6 w-11 rounded-full bg-blue-600' : 'h-6 w-11 rounded-full bg-gray-300'}
    />
  );
}
